namespace DoonPanelPreview {
 public static class ExportTests {
  static int count;static void Check(bool ok,string name){count++;if(!ok)throw new Exception("Export test failed: "+name);}
  static void Reject(Action action,string name){bool rejected=false;try{action();}catch(InvalidOperationException){rejected=true;}catch(InvalidDataException){rejected=true;}catch(IOException){rejected=true;}Check(rejected,name);}
  static T Copy<T>(T value){return PriceParser.Json.Deserialize<T>(PriceParser.Json.Serialize(value));}
  static readonly XNamespace N=KingdeeTemplate.N;
  static XElement Cell(string address,string text){return new XElement(N+"c",new XAttribute("r",address),new XAttribute("s",0),new XAttribute("t","inlineStr"),new XElement(N+"is",new XElement(N+"t",text)));}
  // A small synthetic OOXML protocol fixture, never derived from customer workbooks.
  public static byte[] Template(string kind){var keys=kind=="sales"?KingdeeTemplate.SalesKeys:KingdeeTemplate.MaterialKeys;using(var output=new MemoryStream()){using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true)){
   Action<string,string> add=(path,text)=>{var entry=zip.CreateEntry(path);entry.LastWriteTime=new DateTimeOffset(2026,1,1,0,0,0,TimeSpan.Zero);using(var writer=new StreamWriter(entry.Open(),new UTF8Encoding(false)))writer.Write(text);};
   add("[Content_Types].xml","<Types xmlns='http://schemas.openxmlformats.org/package/2006/content-types'><Default Extension='rels' ContentType='application/vnd.openxmlformats-package.relationships+xml'/><Default Extension='xml' ContentType='application/xml'/><Override PartName='/xl/workbook.xml' ContentType='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml'/><Override PartName='/xl/styles.xml' ContentType='application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml'/><Override PartName='/xl/worksheets/sheet1.xml' ContentType='application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml'/><Override PartName='/xl/worksheets/sheet2.xml' ContentType='application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml'/></Types>");
   add("_rels/.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId1' Target='xl/workbook.xml' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument'/></Relationships>");
   add("xl/workbook.xml","<workbook xmlns='"+N+"' xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets><sheet name='sheet1（名称勿改）' sheetId='1' r:id='rId1'/><sheet name='字典' sheetId='2' state='hidden' r:id='rId2'/></sheets><definedNames><definedName name='Units'>字典!$A$1:$A$2</definedName></definedNames></workbook>");
   add("xl/_rels/workbook.xml.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId1' Target='worksheets/sheet1.xml' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet'/><Relationship Id='rId2' Target='worksheets/sheet2.xml' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet'/><Relationship Id='styles' Target='styles.xml' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles'/></Relationships>");
   add("xl/styles.xml","<styleSheet xmlns='"+N+"'><fonts count='1'><font><sz val='11'/><name val='Calibri'/></font></fonts><fills count='2'><fill><patternFill patternType='none'/></fill><fill><patternFill patternType='gray125'/></fill></fills><borders count='1'><border/></borders><cellStyleXfs count='1'><xf numFmtId='0' fontId='0' fillId='0' borderId='0'/></cellStyleXfs><cellXfs count='1'><xf numFmtId='0' fontId='0' fillId='0' borderId='0' xfId='0'/></cellXfs><cellStyles count='1'><cellStyle name='Normal' xfId='0' builtinId='0'/></cellStyles></styleSheet>");
   var data=new XElement(N+"sheetData",new XElement(N+"row",new XAttribute("r",1),Cell("A1","合成金蝶协议测试")),new XElement(N+"row",new XAttribute("r",3),keys.Select((k,i)=>Cell(XlsxSource.Address(3,i+1),"字段 # "+k))),new XElement(N+"row",new XAttribute("r",4),Cell("A4","OLD-SAMPLE")),new XElement(N+"row",new XAttribute("r",5),Cell("A5","OLD-SAMPLE-2")));
   var validations=new XElement(N+"dataValidations");var options=new Dictionary<string,string>{{"customerid.number","\"C999,C998\""},{"empid.name","\"合成业务员\""},{"currencyid.name","\"人民币,美元\""},{"unit.name","Units"},{"baseunitid.name","Units"},{"parent.number","\"X,Z\""},{"stockid.name","\"合成仓\""}};
   for(int i=0;i<keys.Length;i++)if(options.ContainsKey(keys[i]))validations.Add(new XElement(N+"dataValidation",new XAttribute("type","list"),new XAttribute("sqref",XlsxSource.Address(4,i+1)+":"+XlsxSource.Address(10001,i+1)),new XElement(N+"formula1",options[keys[i]])));validations.SetAttributeValue("count",validations.Elements().Count());
   add("xl/worksheets/sheet1.xml",new XElement(N+"worksheet",new XElement(N+"dimension",new XAttribute("ref","A1:O5")),data,new XElement(N+"mergeCells",new XAttribute("count",1),new XElement(N+"mergeCell",new XAttribute("ref","A4:A5"))),validations,new XElement(N+"pageMargins",new XAttribute("left",0.7),new XAttribute("right",0.7),new XAttribute("top",0.75),new XAttribute("bottom",0.75),new XAttribute("header",0.3),new XAttribute("footer",0.3))).ToString());
   add("xl/worksheets/sheet2.xml",new XElement(N+"worksheet",new XElement(N+"sheetData",new XElement(N+"row",new XAttribute("r",1),Cell("A1","副")),new XElement(N+"row",new XAttribute("r",2),Cell("A2","PCS")))).ToString());
  }return output.ToArray();}}
  public static OrderContext Context(){return new OrderContext{Prices=new List<PriceRow>(),Materials=new List<MaterialRow>(),Rules=new List<CodingRule>{new CodingRule{Category="X",MiddleField="板料编码",Hash="synthetic",File="synthetic-rules.xlsx",Sheet="成品编码规则",Row=2},new CodingRule{Category="Z",MiddleField="电镀颜色",Hash="synthetic",File="synthetic-rules.xlsx",Sheet="成品编码规则",Row=3}},Names=new List<ProductName>{new ProductName{Code="X",Name="合成镜架"},new ProductName{Code="Z",Name="合成金属架"}},Lenses=new List<LensNameRule>{new LensNameRule{Keyword="测试片",Name="合成镜片"}},Fingerprint="synthetic-context",SalesTemplate=KingdeeTemplate.Inspect(Template("sales"),"sales","synthetic-sales.xlsx"),MaterialTemplate=KingdeeTemplate.Inspect(Template("material"),"material","synthetic-material.xlsx")};}
  public static OrderDraft Draft(OrderContext ctx){var file=PriceParser.Parse(SelfTests.Workbook(),"synthetic-order.xlsx");file.Rows=file.Rows.Take(1).ToList();var p=file.Rows[0];p.Category="X";p.Board="ACETATE B001";p.Lens="强化测试片";p.Po="SYNTH-PO";var draft=OrderFlow.Create(file,new[]{"PI"},ctx.Rules);draft.Settings.Salesperson="合成业务员";draft.Settings.Warehouse="合成仓";return draft;}
  static MaterialRow Material(string code,string name="原物料名称"){return new MaterialRow{Code=code,Id=Guid.NewGuid().ToString("N"),File="synthetic.xlsx",Sheet="材料",Row=2,Values=new Dictionary<string,string>{{"物料编码",code},{"物料名称",name},{"规格型号","TEST"},{"基本单位","副"},{"物料分类","X"}}};}
  static void Confirm(OrderDraft draft,OrderContext ctx){var p=OrderFlow.Preview(draft,ctx);if(!p.Ready)throw new Exception(string.Join(";",p.Errors.Concat(p.Lines.SelectMany(l=>l.Errors))));draft.ReviewHash=p.Fingerprint;draft.ReviewedBy="synthetic tester";draft.ReviewedAt=DateTime.UtcNow.ToString("o");}
  static byte[] MisplacedDictionary(){using(var input=new MemoryStream(Template("sales")))using(var zip=new ZipArchive(input,ZipArchiveMode.Read))using(var output=new MemoryStream()){using(var target=new ZipArchive(output,ZipArchiveMode.Create,true))foreach(var entry in zip.Entries)using(var destination=target.CreateEntry(entry.FullName).Open()){if(entry.FullName=="xl/worksheets/sheet2.xml"){var xml=KingdeeTemplate.Xml(zip,entry.FullName);foreach(var cell in xml.Descendants(N+"c"))cell.SetAttributeValue("r",((string)cell.Attribute("r")).Replace("A","I"));using(var writer=new StreamWriter(destination,new UTF8Encoding(false)))writer.Write(xml.ToString());}else using(var source=entry.Open())source.CopyTo(destination);}return output.ToArray();}}
  public static int Run(){count=0;var ctx=Context();var draft=Draft(ctx);var p=OrderFlow.Preview(draft,ctx);Check(p.Ready,"complete new material preview");Check(!ctx.SalesTemplate.Allowed("unit.name","pcs"),"dictionary text must match exact import value");Check(p.Lines[0].IsNew&&p.Lines[0].Code=="X-C999-DN9001-TEST001-B001-C01","six part code");Check(p.Lines[0].Name=="合成镜架（合成镜片）","compound name");Check(p.Lines[0].Price==77.875m&&p.Lines[0].Amount==778.75m,"confirmed decimal conversion");Check(OrderFlow.BoardCode("HAVANA 006439TTN")=="006439TTN"&&OrderFlow.BoardCode("B001 B002")=="","board extraction preserves zeros and blocks ambiguity");
   var misplaced=MisplacedDictionary();var repair=KingdeeTemplate.Inspect(misplaced,"sales","synthetic-misplaced.xlsx");Check(repair.RangeRepairs.Count==1&&repair.Allowed("unit.name","副"),"detect provable misplaced dictionary");var repaired=KingdeeTemplate.Fill(misplaced,repair,OrderExporter.SalesRows(draft,p.Lines));Check(KingdeeTemplate.Inspect(repaired,"sales","repaired.xlsx").RangeRepairs.Count==0,"repair only in export copy");Check(PriceParser.Hash(misplaced)==repair.Hash,"original template unchanged");
   var compound=Copy(draft.Lines[0].Source);compound.RawDrawing="DN9001-GJ-X+Y";compound.Drawing="DN9001-GJ-X+Y";Check(OrderFlow.SourceDrawing(compound,new[]{new CodingRule{Category="X+Y"},new CodingRule{Category="GJ-X+Y"}})=="DN9001","longest complete category suffix");Reject(()=>OrderExporter.Build(draft,ctx,Template("sales"),Template("material")),"review required");Confirm(draft,ctx);byte[] package=OrderExporter.Build(draft,ctx,Template("sales"),Template("material"));using(var input=new MemoryStream(package))using(var zip=new ZipArchive(input,ZipArchiveMode.Read)){Check(zip.Entries.Count==5,"new material package");using(var ms=new MemoryStream()){using(var stream=zip.GetEntry("销售订单-001.xlsx").Open())stream.CopyTo(ms);var bytes=ms.ToArray();var sheets=XlsxSource.Read(bytes);Check(sheets.Count==2&&sheets[1].Hidden,"hidden dictionary retained");Check(sheets[0].Get(4,8).Value==p.Lines[0].Code&&sheets[0].Get(4,11).Value=="77.875","sales mapping");Check(sheets[0].LastRow==4&&sheets[0].Get(4,6).Value=="1","sample removal and CNY rate one");Check(KingdeeTemplate.Inspect(bytes,"sales","check.xlsx").Allowed("unit.name","副"),"named range validation retained");}}
   draft.Settings.Rate="8";Reject(()=>OrderExporter.Build(draft,ctx,Template("sales"),Template("material")),"setting change invalidates review");draft.Settings.Rate="7";ctx.Fingerprint="changed";Reject(()=>OrderExporter.Build(draft,ctx,Template("sales"),Template("material")),"library change invalidates review");ctx.Fingerprint="synthetic-context";
   var row=draft.Lines[0];row.Lens="unknown";Check(!OrderFlow.Preview(draft,ctx).Ready,"unknown lens blocks");row.Lens="测试片";row.Source.Status="单价含公式，仅保留缓存待核对";Check(!OrderFlow.Preview(draft,ctx).Ready,"no formula fallback");row.Source.Status="隐藏工作表";Check(!OrderFlow.Preview(draft,ctx).Ready,"no hidden fallback");row.Source.Status="可匹配";
   row.Customer="C998";Check(!OrderFlow.Preview(draft,ctx).Ready,"changed identity cannot reuse original price");row.Customer="C999";row.UseManualPrice=true;row.ManualPrice="0";row.ManualCurrency="USD";Check(!OrderFlow.Preview(draft,ctx).Ready,"zero needs gift and evidence");row.Gift="是";row.Note="合成赠品依据";Check(OrderFlow.Preview(draft,ctx).Ready,"explicit gift zero");row.UseManualPrice=false;row.Gift="否";row.Note="";
   ctx.Materials.Add(Material(p.Lines[0].Code));p=OrderFlow.Preview(draft,ctx);Check(p.Ready&&!p.Lines[0].IsNew&&p.Lines[0].OriginalName=="原物料名称","exact existing material retained");row.Board="";Check(OrderFlow.Preview(draft,ctx).Ready,"unique material provides missing middle");ctx.Materials.Add(Material("X-C999-DN9001-TEST001-B002-C01"));Check(!OrderFlow.Preview(draft,ctx).Ready,"ambiguous material blocks");row.ChosenCode=ctx.Materials[0].Code;Check(OrderFlow.Preview(draft,ctx).Ready,"explicit compatible choice");ctx.Materials.Add(Material(row.ChosenCode,"冲突名称"));Check(!OrderFlow.Preview(draft,ctx).Ready,"same code conflicting master data blocks");ctx.Materials.Clear();row.ChosenCode="";row.Board="B001";
   ctx.Prices.Add(Copy(row.Source));ctx.Prices[0].UnitPrice="13";Check(!OrderFlow.Preview(draft,ctx).Ready,"conflicting source price blocks");ctx.Prices[0].UnitPrice="12.5";Check(OrderFlow.Preview(draft,ctx).Ready,"customer price match");ctx.Prices.Clear();
   var second=Copy(row);second.Id="synthetic-second";second.Category="Z";second.Frame="Z";second.Plating="银色";draft.Lines.Add(second);p=OrderFlow.Preview(draft,ctx);Check(p.Ready&&p.Lines.Select(l=>l.BillNo).Distinct().Count()==2,"category split before review");Confirm(draft,ctx);using(var ms=new MemoryStream(OrderExporter.Build(draft,ctx,Template("sales"),Template("material"))))using(var zip=new ZipArchive(ms,ZipArchiveMode.Read))Check(zip.Entries.Count(e=>e.FullName.StartsWith("销售订单-"))==2,"category export separation");second.Source=Copy(second.Source);second.Source.Sheet="OTHER VERSION";Check(!OrderFlow.Preview(draft,ctx).Ready,"cross sheet duplicate PI blocked");draft.Lines.Remove(second);
   row.Quantity="0";Check(!OrderFlow.Preview(draft,ctx).Ready,"nonpositive quantity");row.Quantity="10";draft.Settings.Tax="101";Check(!OrderFlow.Preview(draft,ctx).Ready,"invalid tax");draft.Settings.Tax="13";draft.Settings.Salesperson="unknown";Check(!OrderFlow.Preview(draft,ctx).Ready,"unknown employee");draft.Settings.Salesperson="合成业务员";
   string root=Path.Combine(Path.GetTempPath(),"doon-export-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using(var db=new PriceStore(root)){var sfile=Path.Combine(root,"sales.xlsx");var mfile=Path.Combine(root,"material.xlsx");File.WriteAllBytes(sfile,Template("sales"));File.WriteAllBytes(mfile,Template("material"));db.InstallTemplate(sfile,"sales");db.InstallTemplate(mfile,"material");Check(db.CurrentTemplate("sales").Hash==ctx.SalesTemplate.Hash,"template persistence");db.SaveDraft(draft);var stale=Copy(draft);draft.Settings.Rate="8";draft.ReviewHash="";db.SaveDraft(draft);Check(db.Drafts().Single().Version==2,"draft immutable versions");Reject(()=>db.SaveDraft(stale),"concurrent draft edit blocked");Check(db.All().Count==0&&db.MaterialCount()==0,"drafts do not mutate business libraries");Check(db.Integrity()=="ok","export schema integrity");
    db.ImportCoding(CodingParser.Parse(CodingTests.Fixture(),"synthetic-rules.xlsx"));string config=Path.Combine(root,"names.json");foreach(var name in ctx.Names)name.Source="synthetic";File.WriteAllText(config,PriceParser.Json.Serialize(ctx.Names));db.ImportNames(config);config=Path.Combine(root,"lenses.json");foreach(var lens in ctx.Lenses)lens.Source="synthetic";File.WriteAllText(config,PriceParser.Json.Serialize(ctx.Lenses));db.ImportLensRules(config);var original=PriceParser.Parse(SelfTests.Workbook(),"synthetic-order.xlsx");db.ArchiveOrder(original);var live=db.OrderContext();draft.Settings.Rate="7";Confirm(draft,live);db.SaveDraft(draft);string destination=Path.Combine(root,"confirmed.zip");string exported=OrderExporter.Save(db,draft,destination);Check(PriceParser.Hash(File.ReadAllBytes(destination))==exported&&db.ExportHistory().Count==1,"full saved export and audit readback");Reject(()=>OrderExporter.Save(db,draft,destination),"never overwrite previous export");Check(db.ExportHistory().Count==1,"failed repeat has no audit success");string archive=Path.Combine(root,"originals",original.Hash+".xlsx");File.WriteAllText(archive,"synthetic-corruption");Reject(()=>OrderExporter.Save(db,draft,Path.Combine(root,"blocked.zip")),"changed original archive blocks export");}}
   finally{var absolute=Path.GetFullPath(root);if(absolute.StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(absolute).StartsWith("doon-export-test-"))Directory.Delete(absolute,true);}return count;
  }
 }
